-- PostgreSQL migration target v1, deliberately distinct from SQLite DDL.
-- Canonical timestamps and JSON are TEXT to preserve source bytes/checksums.
-- Integer cells use BIGINT, with string transport in the NDJSON importer.
-- This staging target does not enable the live application's write triggers.
-- Cutover requires the production PostgreSQL repository and security review.
CREATE TABLE IF NOT EXISTS category(id TEXT PRIMARY KEY,name TEXT NOT NULL,parent_id TEXT REFERENCES category(id) DEFERRABLE INITIALLY DEFERRED,sort_order BIGINT NOT NULL DEFAULT 0,CHECK(parent_id IS NULL OR parent_id<>id));
CREATE TABLE IF NOT EXISTS content(id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,locale TEXT NOT NULL DEFAULT 'en',title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',alt_text TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN ('draft','processing','ready_for_review','published','archived')),latest_version BIGINT NOT NULL DEFAULT 1,active_version BIGINT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,published_at TEXT,sort_score BIGINT NOT NULL DEFAULT 0,difficulty TEXT CHECK(difficulty IN ('easy','detailed') OR difficulty IS NULL),example_only BIGINT NOT NULL DEFAULT 0,provenance_json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS content_published_date ON content(status,published_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS content_published_score ON content(status,sort_score DESC,id DESC);
CREATE INDEX IF NOT EXISTS content_published_title ON content(status,lower(title),id);
CREATE INDEX IF NOT EXISTS content_difficulty ON content(status,difficulty,published_at DESC,id DESC);
CREATE TABLE IF NOT EXISTS content_revision(content_id TEXT NOT NULL REFERENCES content(id) DEFERRABLE INITIALLY DEFERRED,version BIGINT NOT NULL,manifest_json TEXT NOT NULL,manifest_sha256 TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'ready_for_review',created_at TEXT NOT NULL,PRIMARY KEY(content_id,version));
CREATE TABLE IF NOT EXISTS content_category(content_id TEXT NOT NULL REFERENCES content(id) DEFERRABLE INITIALLY DEFERRED,category_id TEXT NOT NULL REFERENCES category(id) DEFERRABLE INITIALLY DEFERRED,position BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(content_id,category_id));
CREATE INDEX IF NOT EXISTS category_content ON content_category(category_id,content_id);
CREATE TABLE IF NOT EXISTS content_tag(content_id TEXT NOT NULL REFERENCES content(id) DEFERRABLE INITIALLY DEFERRED,tag TEXT NOT NULL,PRIMARY KEY(content_id,tag));
CREATE INDEX IF NOT EXISTS tag_content ON content_tag(tag,content_id);
CREATE TABLE IF NOT EXISTS content_age(content_id TEXT NOT NULL REFERENCES content(id) DEFERRABLE INITIALLY DEFERRED,age TEXT NOT NULL CHECK(age IN ('kids','teens','adults')),PRIMARY KEY(content_id,age));
CREATE INDEX IF NOT EXISTS age_content ON content_age(age,content_id);
CREATE TABLE IF NOT EXISTS asset(asset_id TEXT PRIMARY KEY,content_id TEXT NOT NULL REFERENCES content(id) DEFERRABLE INITIALLY DEFERRED,content_version BIGINT NOT NULL,role TEXT NOT NULL,object_key TEXT NOT NULL,original_key TEXT NOT NULL,mime TEXT NOT NULL,bytes BIGINT NOT NULL CHECK(bytes>0),sha256 TEXT NOT NULL,width BIGINT,height BIGINT,page_count BIGINT,asset_version BIGINT NOT NULL,verified BIGINT NOT NULL DEFAULT 0,UNIQUE(content_id,content_version,role));
CREATE INDEX IF NOT EXISTS asset_content ON asset(content_id,content_version,role);
CREATE TABLE IF NOT EXISTS asset_review(sha256 TEXT NOT NULL,role TEXT NOT NULL,mime TEXT NOT NULL,bytes BIGINT NOT NULL,width BIGINT,height BIGINT,page_count BIGINT,bw BIGINT NOT NULL,review_version BIGINT NOT NULL DEFAULT 1,reviewed_at TEXT NOT NULL,PRIMARY KEY(sha256,role));
CREATE TABLE IF NOT EXISTS slug_redirect(old_slug TEXT PRIMARY KEY,content_id TEXT NOT NULL REFERENCES content(id) DEFERRABLE INITIALLY DEFERRED,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS import_job(id TEXT PRIMARY KEY,idempotency_key TEXT NOT NULL UNIQUE,payload_sha256 TEXT NOT NULL,status TEXT NOT NULL,owner TEXT NOT NULL,total BIGINT NOT NULL DEFAULT 1,error_code TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS import_item(import_id TEXT NOT NULL REFERENCES import_job(id) DEFERRABLE INITIALLY DEFERRED,content_id TEXT NOT NULL,version BIGINT NOT NULL,status TEXT NOT NULL,error_code TEXT,PRIMARY KEY(import_id,content_id));
CREATE TABLE IF NOT EXISTS outbox_event(seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_id TEXT NOT NULL UNIQUE,content_id TEXT NOT NULL,version BIGINT NOT NULL,event_type TEXT NOT NULL,created_at TEXT NOT NULL,delivered_at TEXT,processed_at TEXT,attempts BIGINT NOT NULL DEFAULT 0,last_error TEXT);
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox_event(processed_at,seq);
CREATE TABLE IF NOT EXISTS processed_event(event_id TEXT PRIMARY KEY,processed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_event(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,target_id TEXT NOT NULL,version BIGINT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS category_count(category_id TEXT PRIMARY KEY REFERENCES category(id) DEFERRABLE INITIALLY DEFERRED,published_count BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS creator_job(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,payload_sha256 TEXT NOT NULL,parameters_json TEXT NOT NULL,source_revision TEXT NOT NULL,input_key TEXT,model TEXT NOT NULL,status TEXT NOT NULL,reservation_micros BIGINT NOT NULL,daily_limit_micros BIGINT NOT NULL,monthly_limit_micros BIGINT NOT NULL,concurrent_limit BIGINT NOT NULL,session_limit BIGINT NOT NULL,error_code TEXT,line_art_key TEXT,color_preview_key TEXT,pdf_key TEXT,width BIGINT,height BIGINT,actual_cost_micros BIGINT,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,started_at TEXT,completed_at TEXT,UNIQUE(owner_id,idempotency_key));
CREATE INDEX IF NOT EXISTS creator_owner ON creator_job(owner_id,created_at DESC);
CREATE INDEX IF NOT EXISTS creator_budget ON creator_job(created_at,status);
CREATE TABLE IF NOT EXISTS creator_upload(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,object_key TEXT NOT NULL,mime TEXT NOT NULL,bytes BIGINT NOT NULL,sha256 TEXT NOT NULL,status TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS capacity_snapshot(database_role TEXT PRIMARY KEY,bytes BIGINT NOT NULL,measured_at TEXT NOT NULL,limit_bytes BIGINT NOT NULL DEFAULT 10000000000);
CREATE TABLE IF NOT EXISTS request_limit(scope TEXT NOT NULL,key_hash TEXT NOT NULL,window_start BIGINT NOT NULL,count BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(scope,key_hash,window_start));
CREATE INDEX IF NOT EXISTS request_limit_expiry ON request_limit(window_start);
CREATE TABLE IF NOT EXISTS sitemap_entry(ordinal BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,content_id TEXT NOT NULL UNIQUE REFERENCES content(id) DEFERRABLE INITIALLY DEFERRED,slug TEXT NOT NULL,updated_at TEXT NOT NULL,visibility TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sitemap_visibility_ordinal ON sitemap_entry(visibility,ordinal);
CREATE TABLE IF NOT EXISTS ai_free_reservation(job_id TEXT PRIMARY KEY REFERENCES creator_job(id) DEFERRABLE INITIALLY DEFERRED,day TEXT NOT NULL,neurons BIGINT NOT NULL CHECK(neurons>0),daily_limit BIGINT NOT NULL CHECK(daily_limit BETWEEN 1 AND 10000),provider_receipt TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ai_free_day ON ai_free_reservation(day);
CREATE TABLE IF NOT EXISTS transfer_checkpoint(snapshot_sha256 TEXT PRIMARY KEY,last_line BIGINT NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'importing',updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS migration_event(event_id TEXT PRIMARY KEY,content_id TEXT NOT NULL,version BIGINT NOT NULL,payload_sha256 TEXT NOT NULL,disposition TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS search_projection(id TEXT PRIMARY KEY REFERENCES content(id) DEFERRABLE INITIALLY DEFERRED,source_version BIGINT NOT NULL,visibility TEXT NOT NULL,locale TEXT NOT NULL,title TEXT NOT NULL,tags TEXT NOT NULL,categories TEXT NOT NULL,category_ids TEXT[] NOT NULL,age_groups TEXT[] NOT NULL,difficulty TEXT,published_at TEXT,sort_score BIGINT NOT NULL DEFAULT 0,document TSVECTOR GENERATED ALWAYS AS (setweight(to_tsvector('simple'::regconfig,title),'A') || setweight(to_tsvector('simple'::regconfig,tags),'B') || setweight(to_tsvector('simple'::regconfig,categories),'C')) STORED);
CREATE INDEX IF NOT EXISTS search_projection_gin ON search_projection USING GIN(document);
CREATE INDEX IF NOT EXISTS search_projection_visibility ON search_projection(visibility,sort_score DESC,id DESC);

CREATE TABLE IF NOT EXISTS age_recommendation(content_id TEXT PRIMARY KEY REFERENCES content(id) DEFERRABLE INITIALLY DEFERRED,content_version BIGINT NOT NULL CHECK(content_version>0),source_sha256 TEXT NOT NULL CHECK(length(source_sha256)=64),band TEXT NOT NULL CHECK(band IN ('3-5','6-8','9-12','13-17','adults')),score_hundredths BIGINT NOT NULL CHECK(score_hundredths BETWEEN 0 AND 10000),method_version TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS age_recommendation_band ON age_recommendation(band,content_id);
ALTER TABLE search_projection ADD COLUMN IF NOT EXISTS recommended_age TEXT;
CREATE INDEX IF NOT EXISTS search_recommended_age ON search_projection(visibility,recommended_age,id);

CREATE INDEX IF NOT EXISTS age_recommendation_detail ON age_recommendation(score_hundredths,content_id,content_version);

-- Source-bound color jobs and quota receipts must survive a catalog transfer.
-- Color inspiration is an optional derivative, never a change to accepted artwork.
CREATE TABLE color_reference_job (
 job_key TEXT PRIMARY KEY,
 content_id TEXT NOT NULL REFERENCES content(id) DEFERRABLE INITIALLY DEFERRED,
 source_sha256 TEXT NOT NULL,
 preview_sha256 TEXT NOT NULL,
 engine TEXT NOT NULL DEFAULT 'pixel-conditioned-v3',
 state TEXT NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','processing','ready','retry','review_needed','obsolete')),
 attempts BIGINT NOT NULL DEFAULT 0,
 request_id TEXT,
 lease_until TEXT,
 not_before TEXT NOT NULL DEFAULT '',
 error_code TEXT,
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 UNIQUE(content_id,source_sha256,preview_sha256,engine)
);
CREATE INDEX color_reference_work ON color_reference_job(state,not_before,created_at);
CREATE TABLE color_reference_scan (id BIGINT PRIMARY KEY CHECK(id=1), after_id TEXT NOT NULL DEFAULT '');

CREATE TABLE color_ai_reservation (
 request_id TEXT PRIMARY KEY,
 job_key TEXT NOT NULL REFERENCES color_reference_job(job_key) DEFERRABLE INITIALLY DEFERRED,
 day TEXT NOT NULL,
 neurons BIGINT NOT NULL CHECK(neurons IN (300,600)),
 daily_limit BIGINT NOT NULL CHECK(daily_limit BETWEEN 300 AND 9000),
 provider_receipt TEXT,
 created_at TEXT NOT NULL
);
CREATE INDEX color_ai_day ON color_ai_reservation(day);

CREATE TABLE discovery_dirty(segment TEXT PRIMARY KEY,generation BIGINT NOT NULL DEFAULT 1);
CREATE TABLE discovery_fragment(segment TEXT PRIMARY KEY,object_key TEXT NOT NULL,etag TEXT NOT NULL,url_count BIGINT NOT NULL,bytes BIGINT NOT NULL,generated_at TEXT NOT NULL,generation BIGINT NOT NULL);
CREATE TABLE discovery_page(path_key TEXT PRIMARY KEY,lastmod TEXT NOT NULL);
CREATE TABLE discovery_state(id BIGINT PRIMARY KEY CHECK(id=1),epoch BIGINT NOT NULL DEFAULT 0,reconcile_after BIGINT NOT NULL DEFAULT 0);
CREATE TABLE discovery_notice(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,path_key TEXT NOT NULL,content_id TEXT,revision TEXT NOT NULL,event_type TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',attempts BIGINT NOT NULL DEFAULT 0,not_before TEXT NOT NULL DEFAULT '',lease_until TEXT,last_status BIGINT,last_error TEXT,received_at TEXT,created_at TEXT NOT NULL,UNIQUE(path_key,revision,event_type));
CREATE INDEX discovery_notice_due ON discovery_notice(state,not_before,id);
